fn dashboard_request_authorized(
    state: &GatewayState,
    headers: &HeaderMap,
    query_token: Option<&str>,
) -> bool {
    query_token
        .into_iter()
        .chain(dashboard_header_token(headers))
        .chain(dashboard_bearer_token(headers))
        .chain(dashboard_cookie_token(headers))
        .any(|token| state.dashboard_session.is_valid(token))
}

fn dashboard_chart_options(
    surface: DashboardChartSurface,
    query: &DashboardQuery,
    headers: &HeaderMap,
) -> (DashboardChartOptions, Option<String>) {
    let pins = dashboard_pin_state_from_request(headers, surface, query.pin.as_deref());
    (
        DashboardChartOptions {
            surface,
            selected_tier: dashboard_normalize_tier(query.tier.as_deref()),
            selected_timeframe: DashboardPriceTimeframe::from_query(query.tf.as_deref()),
            selected_bucket: query
                .bucket
                .as_deref()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_owned),
            selected_quant: query
                .quant
                .as_deref()
                .map(normalize_quant_bucket)
                .and_then(Result::ok),
            selected_unit: query
                .unit
                .as_deref()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_owned),
            selected_speciality: dashboard_parse_speciality_filter(query.speciality.as_deref()),
            pinned_models: pins.models,
            provider_filter: query
                .provider
                .as_deref()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_owned),
        },
        pins.set_cookie,
    )
}

fn dashboard_parse_speciality_filter(value: Option<&str>) -> Option<(String, String)> {
    let value = value?.trim();
    let (name, level) = value.split_once('=')?;
    let name = name.trim();
    let level = level.trim();
    let valid = |component: &str| {
        !component.is_empty()
            && component.len() <= 128
            && component
                .bytes()
                .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'.' | b'-'))
    };
    if !valid(name) || !valid(level) || level.contains('=') {
        return None;
    }
    Some((name.to_owned(), level.to_owned()))
}

fn dashboard_pin_state_from_request(
    headers: &HeaderMap,
    surface: DashboardChartSurface,
    query_pin: Option<&str>,
) -> DashboardPinState {
    if let Some(query_pin) = query_pin {
        let models = dashboard_parse_pin_list(query_pin);
        return DashboardPinState {
            set_cookie: Some(dashboard_pin_cookie_value(surface, &models)),
            models,
        };
    }
    let models = dashboard_cookie_named(headers, surface.pin_cookie_name())
        .map(dashboard_parse_pin_list)
        .unwrap_or_default();
    DashboardPinState {
        models,
        set_cookie: None,
    }
}

fn dashboard_parse_pin_list(value: &str) -> Vec<String> {
    let mut seen = BTreeSet::new();
    value
        .split(',')
        .filter_map(|entry| {
            let decoded = dashboard_url_decode(entry);
            let trimmed = decoded.trim();
            if trimmed.is_empty() || trimmed.eq_ignore_ascii_case("clear") {
                return None;
            }
            let model = trimmed.chars().take(160).collect::<String>();
            if seen.insert(model.clone()) {
                Some(model)
            } else {
                None
            }
        })
        .take(12)
        .collect()
}

fn dashboard_pin_cookie_value(surface: DashboardChartSurface, models: &[String]) -> String {
    let value = models
        .iter()
        .map(|model| dashboard_url_encode(model))
        .collect::<Vec<_>>()
        .join(",");
    format!(
        "{}={value}; Path=/mayhem/dashboard; Max-Age={DASHBOARD_PIN_COOKIE_MAX_AGE_SECONDS}; SameSite=Strict",
        surface.pin_cookie_name()
    )
}

fn dashboard_header_token(headers: &HeaderMap) -> Option<&str> {
    headers
        .get("x-mayhem-dashboard-token")
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn dashboard_bearer_token(headers: &HeaderMap) -> Option<&str> {
    headers
        .get(header::AUTHORIZATION)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.trim().strip_prefix("Bearer "))
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn dashboard_cookie_token(headers: &HeaderMap) -> Option<&str> {
    dashboard_cookie_named(headers, DASHBOARD_COOKIE_NAME)
}

fn dashboard_cookie_named<'a>(headers: &'a HeaderMap, cookie_name: &str) -> Option<&'a str> {
    headers
        .get(header::COOKIE)
        .and_then(|value| value.to_str().ok())
        .and_then(|cookie| {
            cookie.split(';').find_map(|part| {
                let (name, value) = part.trim().split_once('=')?;
                (name == cookie_name).then_some(value.trim())
            })
        })
        .filter(|value| !value.is_empty())
}

fn dashboard_html_response(status: StatusCode, body: String, token: Option<&str>) -> Response {
    dashboard_html_response_with_extra_cookie(status, body, token, None)
}

fn dashboard_html_response_with_extra_cookie(
    status: StatusCode,
    body: String,
    token: Option<&str>,
    extra_cookie: Option<&str>,
) -> Response {
    let mut response = (status, body).into_response();
    response.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("text/html; charset=utf-8"),
    );
    if let Some(token) = token {
        if let Ok(value) = HeaderValue::from_str(&dashboard_cookie_value(token)) {
            response.headers_mut().append(header::SET_COOKIE, value);
        }
    }
    if let Some(cookie) = extra_cookie {
        if let Ok(value) = HeaderValue::from_str(cookie) {
            response.headers_mut().append(header::SET_COOKIE, value);
        }
    }
    with_dashboard_security_headers(response)
}

fn dashboard_json_response(status: StatusCode, body: Value, token: Option<&str>) -> Response {
    let mut response = (status, Json(body)).into_response();
    if let Some(token) = token {
        if let Ok(value) = HeaderValue::from_str(&dashboard_cookie_value(token)) {
            response.headers_mut().insert(header::SET_COOKIE, value);
        }
    }
    with_dashboard_security_headers(response)
}

fn dashboard_cookie_value(token: &str) -> String {
    format!(
        "{DASHBOARD_COOKIE_NAME}={token}; Path=/mayhem/dashboard; Max-Age={DASHBOARD_SESSION_TTL_SECONDS}; HttpOnly; SameSite=Strict"
    )
}

fn with_dashboard_security_headers(mut response: Response) -> Response {
    let headers = response.headers_mut();
    headers.insert(
        header::CONTENT_SECURITY_POLICY,
        HeaderValue::from_static(DASHBOARD_CSP),
    );
    headers.insert(header::CACHE_CONTROL, HeaderValue::from_static("no-store"));
    headers.insert("x-frame-options", HeaderValue::from_static("DENY"));
    headers.insert("referrer-policy", HeaderValue::from_static("no-referrer"));
    response
}

fn dashboard_origin_from_headers(headers: &HeaderMap) -> String {
    headers
        .get(header::HOST)
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .filter(|host| host.starts_with("127.0.0.1"))
        .map(|host| format!("http://{host}"))
        .unwrap_or_else(|| "http://127.0.0.1".to_owned())
}

fn dashboard_locked_html(expires_in_seconds: u64) -> String {
    dashboard_html_document(
        "Locked",
        &format!(
            r#"<main class="dashboard"><section class="card strong"><span class="label">Local session</span><h1 class="wordmark compact">MAY<span class="hem">HEM</span></h1><p class="muted">Dashboard token required.</p><p class="mono">expires in {expires_in_seconds}s</p></section></main>"#
        ),
    )
}

fn dashboard_tier_tooltip() -> &'static str {
    "Tier 1: runs Mayhem software; trust is economic. Tier 2: proven Apple or NVIDIA hardware running the real app. Tier 3: Only Tier 3 keeps prompts private from the provider's own machine. Tier 4: admin-verified business identity, not prompt privacy; Tier 4 can still read prompts. Higher numbers are not a privacy ladder."
}

fn dashboard_update_banner(notice: Option<&GatewayUpdateNotice>) -> String {
    let Some(notice) = notice else {
        return String::new();
    };
    let class = if notice.level == "required" {
        "update-banner required"
    } else {
        "update-banner"
    };
    let label = if notice.level == "required" {
        "Update required"
    } else {
        "Update available"
    };
    format!(
        r#"<section class="{class}" role="status"><span class="label">{}</span><p>{}</p><p class="mono">installed v{} / catalog min v{} / {} affected model(s)</p></section>"#,
        html_escape(label),
        html_escape(&notice.message),
        html_escape(&notice.installed_app_version),
        html_escape(&notice.required_min_app_version),
        notice.affected_model_count,
    )
}

fn installed_app_version() -> &'static str {
    env!("CARGO_PKG_VERSION")
}

fn gateway_update_notice(
    models: &[GatewayModel],
    hidden_update_models: &[GatewayUpdateModelNotice],
) -> Option<GatewayUpdateNotice> {
    let mut notices = BTreeMap::<String, GatewayUpdateModelNotice>::new();
    let mut hidden_ids = BTreeSet::<String>::new();
    for notice in hidden_update_models {
        if notice.model_id.trim().is_empty() || notice.min_app_version.trim().is_empty() {
            continue;
        }
        hidden_ids.insert(notice.model_id.clone());
        notices.insert(notice.model_id.clone(), notice.clone());
    }
    for model in models {
        if let Some(notice) = gateway_model_update_notice(model) {
            notices.entry(notice.model_id.clone()).or_insert(notice);
        }
    }
    if notices.is_empty() {
        return None;
    }
    let models = notices.into_values().collect::<Vec<_>>();
    let required_min_app_version = highest_min_app_version(&models);
    let installed_app_version = models
        .first()
        .map(|notice| notice.installed_app_version.clone())
        .unwrap_or_else(|| installed_app_version().to_owned());
    let affected_model_count = models.len();
    let hidden_model_count = models
        .iter()
        .filter(|notice| hidden_ids.contains(&notice.model_id))
        .count();
    let level = if hidden_model_count > 0 {
        "required"
    } else {
        "available"
    }
    .to_owned();
    let message = if hidden_model_count > 0 {
        format!(
            "Update required: this app is v{installed_app_version}, catalog requires >= v{required_min_app_version} for {affected_model_count} model(s); {hidden_model_count} model(s) are hidden until you update (run `mayhem update`)."
        )
    } else {
        format!(
            "Update available: this app is v{installed_app_version}, catalog requires >= v{required_min_app_version} for {affected_model_count} model(s) (run `mayhem update`)."
        )
    };
    Some(GatewayUpdateNotice {
        level,
        installed_app_version,
        required_min_app_version,
        affected_model_count,
        hidden_model_count,
        message,
        models,
    })
}

fn gateway_model_update_notice(model: &GatewayModel) -> Option<GatewayUpdateModelNotice> {
    let min_app_version = model
        .mayhem
        .min_app_version
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())?;
    let installed_app_version = installed_app_version();
    if gateway_app_version_satisfies_min(installed_app_version, min_app_version).unwrap_or(true) {
        return None;
    }
    Some(GatewayUpdateModelNotice {
        model_id: model.id.clone(),
        min_app_version: min_app_version.to_owned(),
        installed_app_version: installed_app_version.to_owned(),
        message: gateway_update_model_message(&model.id, min_app_version, installed_app_version),
    })
}

fn gateway_app_version_satisfies_min(installed: &str, min_app_version: &str) -> Option<bool> {
    let installed = semver::Version::parse(installed.trim()).ok()?;
    let min_app_version = semver::Version::parse(min_app_version.trim()).ok()?;
    Some(installed >= min_app_version)
}

fn highest_min_app_version(notices: &[GatewayUpdateModelNotice]) -> String {
    let mut highest: Option<(semver::Version, String)> = None;
    for notice in notices {
        let Ok(version) = semver::Version::parse(notice.min_app_version.trim()) else {
            continue;
        };
        if highest
            .as_ref()
            .map_or(true, |(current, _)| version > *current)
        {
            highest = Some((version, notice.min_app_version.clone()));
        }
    }
    highest
        .map(|(_, value)| value)
        .unwrap_or_else(|| notices[0].min_app_version.clone())
}

fn gateway_update_model_message(
    model_id: &str,
    min_app_version: &str,
    installed_app_version: &str,
) -> String {
    format!(
        "model {model_id} requires Mayhem >= {min_app_version}; installed {installed_app_version}; run `mayhem update`"
    )
}

fn dashboard_payment_status(state: &GatewayState) -> String {
    let rail = state.receipt_config.rail.as_str();
    let Some(directory) = state.payment_directory() else {
        return html_escape(&format!(
            "{} credit · ledger directory unavailable",
            rail.to_uppercase()
        ));
    };
    let text = match rail {
        "tap" | "tnk" => {
            let rate = directory.get("rates").and_then(|rates| rates.get(rail));
            let usd = rate
                .and_then(|rate| rate.get("usd"))
                .and_then(Value::as_str)
                .unwrap_or("unavailable");
            let source = rate
                .and_then(|rate| rate.get("source"))
                .and_then(Value::as_str)
                .unwrap_or("ledger");
            let age = rate
                .and_then(|rate| rate.get("age_seconds"))
                .and_then(Value::as_u64)
                .map(|value| format!(" · {value}s old"))
                .unwrap_or_default();
            format!(
                "{} credit · ${}/{} · {}{}",
                rail.to_uppercase(),
                usd,
                rail.to_uppercase(),
                source,
                age
            )
        }
        "fiat" => {
            let currencies = directory
                .pointer("/payments/fiat/currencies")
                .and_then(Value::as_array)
                .map(|values| {
                    values
                        .iter()
                        .filter_map(Value::as_str)
                        .map(str::to_uppercase)
                        .collect::<Vec<_>>()
                        .join("/")
                })
                .filter(|value| !value.is_empty())
                .unwrap_or_else(|| "USD/EUR".to_owned());
            format!("Fiat credit · Stripe hosted checkout · {currencies}")
        }
        other => format!("{} credit · canonical Trac ledger", other.to_uppercase()),
    };
    html_escape(&text)
}

