fn canary_registry_from_catalog_root(
    root: &Value,
    canary_sets: &BTreeMap<String, Vec<GatewayCanaryPrompt>>,
) -> GatewayCanaryRegistry {
    let mut models = BTreeMap::new();
    let Some(model_values) = root.get("models").and_then(Value::as_array) else {
        return GatewayCanaryRegistry { models };
    };
    for model in model_values {
        let Some(model_id) = model.get("model_id").and_then(Value::as_str) else {
            continue;
        };
        let Some(canary) = model.get("canary") else {
            continue;
        };
        let Some(canary_set) = canary.get("set_id").and_then(Value::as_str) else {
            continue;
        };
        let requires_launch_evidence = model.get("tier").and_then(Value::as_str) == Some("launch");
        let Some(prompts) = canary_sets.get(canary_set).cloned() else {
            continue;
        };
        let match_min_bps = canary
            .get("match_min")
            .and_then(Value::as_f64)
            .map(|value| (value * 10_000.0).round().clamp(0.0, 10_000.0) as u32)
            .unwrap_or(DEFAULT_CANARY_MATCH_MIN_BPS);
        let verification_method = canary
            .get("verification_method")
            .and_then(Value::as_str)
            .unwrap_or(CANARY_VERIFICATION_TOKEN_FINGERPRINT)
            .to_owned();
        if !supported_canary_verification_method(&verification_method) {
            continue;
        }
        let verification_tolerance_bps = canary
            .get("verification_tolerance_bps")
            .and_then(Value::as_u64)
            .and_then(|value| u32::try_from(value).ok());
        let fingerprints = canary
            .get("fingerprints")
            .and_then(Value::as_object)
            .into_iter()
            .flat_map(|object| object.iter())
            .filter_map(|(artifact_name, value)| {
                value
                    .as_str()
                    .map(|fingerprint| (artifact_name.as_str(), fingerprint.to_owned()))
            })
            .collect::<BTreeMap<_, _>>();
        let token_prefixes = canary_token_prefixes_by_artifact(canary);
        if verification_method == CANARY_VERIFICATION_TOKEN_FINGERPRINT
            && (fingerprints.is_empty() || token_prefixes.is_empty())
        {
            continue;
        }
        let perceptual_hashes = canary_perceptual_hashes_by_artifact(canary);
        if verification_method == CANARY_VERIFICATION_SEED_PERCEPTUAL_HASH
            && perceptual_hashes.is_empty()
        {
            continue;
        }
        let embedding_vectors = canary_embedding_vectors_by_artifact(canary);
        if verification_method == CANARY_VERIFICATION_EMBEDDING_COSINE
            && embedding_vectors.is_empty()
        {
            continue;
        }
        let transcripts = canary_transcripts_by_artifact(canary);
        if verification_method == CANARY_VERIFICATION_TRANSCRIPT_MATCH && transcripts.is_empty() {
            continue;
        }
        let audio_fingerprints = canary_audio_fingerprints_by_artifact(canary);
        if verification_method == CANARY_VERIFICATION_AUDIO_FINGERPRINT
            && audio_fingerprints.is_empty()
        {
            continue;
        }
        let mut fingerprints_by_artifact_root = BTreeMap::new();
        let mut token_prefixes_by_artifact_root = BTreeMap::new();
        let mut perceptual_hashes_by_artifact_root = BTreeMap::new();
        let mut embedding_vectors_by_artifact_root = BTreeMap::new();
        let mut transcripts_by_artifact_root = BTreeMap::new();
        let mut audio_fingerprints_by_artifact_root = BTreeMap::new();
        let speciality_calibrations = speciality_calibrations_from_catalog_value(model);
        let mut speciality_calibrations_by_artifact_root = BTreeMap::new();
        if let Some(artifacts) = model.get("artifacts").and_then(Value::as_object) {
            for (artifact_name, artifact) in artifacts {
                if let Some(artifact_root) = artifact.get("artifact_root").and_then(Value::as_str) {
                    if let Some(calibrations) = speciality_calibrations.get(artifact_name) {
                        speciality_calibrations_by_artifact_root
                            .insert(artifact_root.to_owned(), calibrations.clone());
                    }
                    if verification_method == CANARY_VERIFICATION_TOKEN_FINGERPRINT {
                        let Some(fingerprint) = fingerprints.get(artifact_name.as_str()) else {
                            continue;
                        };
                        let Some(prefixes) = token_prefixes.get(artifact_name.as_str()) else {
                            continue;
                        };
                        let expected_fingerprint =
                            aggregate_token_prefixes_for_prompts(&prompts, prefixes);
                        if expected_fingerprint.as_deref() != Some(fingerprint.as_str()) {
                            continue;
                        }
                        fingerprints_by_artifact_root
                            .insert(artifact_root.to_owned(), fingerprint.clone());
                        token_prefixes_by_artifact_root
                            .insert(artifact_root.to_owned(), prefixes.clone());
                    } else if let Some(hashes) = perceptual_hashes.get(artifact_name.as_str()) {
                        perceptual_hashes_by_artifact_root
                            .insert(artifact_root.to_owned(), hashes.clone());
                    } else if let Some(vectors) = embedding_vectors.get(artifact_name.as_str()) {
                        embedding_vectors_by_artifact_root
                            .insert(artifact_root.to_owned(), vectors.clone());
                    } else if let Some(expected) = transcripts.get(artifact_name.as_str()) {
                        transcripts_by_artifact_root
                            .insert(artifact_root.to_owned(), expected.clone());
                    } else if let Some(expected) = audio_fingerprints.get(artifact_name.as_str()) {
                        audio_fingerprints_by_artifact_root
                            .insert(artifact_root.to_owned(), expected.clone());
                    }
                }
            }
        }
        let default_fingerprint = fingerprints.values().next().cloned();
        let default_token_prefixes = token_prefixes.values().next().cloned();
        let default_perceptual_hashes = perceptual_hashes.values().next().cloned();
        let default_embedding_vectors = embedding_vectors.values().next().cloned();
        let default_transcripts = transcripts.values().next().cloned();
        let default_audio_fingerprints = audio_fingerprints.values().next().cloned();
        models.insert(
            model_id.to_owned(),
            GatewayCanaryModelConfig {
                canary_set: canary_set.to_owned(),
                requires_launch_evidence,
                match_min_bps,
                verification_method,
                verification_tolerance_bps,
                prompts,
                fingerprints_by_artifact_root,
                token_prefixes_by_artifact_root,
                perceptual_hashes_by_artifact_root,
                embedding_vectors_by_artifact_root,
                transcripts_by_artifact_root,
                audio_fingerprints_by_artifact_root,
                speciality_calibrations_by_artifact_root,
                default_fingerprint,
                default_token_prefixes,
                default_perceptual_hashes,
                default_embedding_vectors,
                default_transcripts,
                default_audio_fingerprints,
            },
        );
    }
    GatewayCanaryRegistry { models }
}

fn canary_token_prefixes_by_artifact(
    canary: &Value,
) -> BTreeMap<String, BTreeMap<String, Vec<i32>>> {
    canary
        .get("token_prefixes")
        .and_then(Value::as_object)
        .into_iter()
        .flat_map(|object| object.iter())
        .filter_map(|(artifact_name, value)| {
            let prompts = value.as_object()?;
            let prefixes = prompts
                .iter()
                .filter_map(|(prompt_id, raw_tokens)| {
                    let tokens = raw_tokens
                        .as_array()?
                        .iter()
                        .map(|token| token.as_i64().and_then(|token| i32::try_from(token).ok()))
                        .collect::<Option<Vec<_>>>()?;
                    (!tokens.is_empty()).then_some((prompt_id.clone(), tokens))
                })
                .collect::<BTreeMap<_, _>>();
            (!prefixes.is_empty()).then_some((artifact_name.clone(), prefixes))
        })
        .collect()
}

fn canary_perceptual_hashes_by_artifact(
    canary: &Value,
) -> BTreeMap<String, BTreeMap<String, String>> {
    canary
        .get("perceptual_hashes")
        .and_then(Value::as_object)
        .into_iter()
        .flat_map(|object| object.iter())
        .filter_map(|(artifact_name, value)| {
            let prompts = value.as_object()?;
            let prompts = prompts
                .iter()
                .filter_map(|(prompt_id, hash)| {
                    hash.as_str()
                        .filter(|hash| !hash.is_empty())
                        .map(|hash| (prompt_id.clone(), hash.to_owned()))
                })
                .collect::<BTreeMap<_, _>>();
            (!prompts.is_empty()).then(|| (artifact_name.clone(), prompts))
        })
        .collect()
}

fn canary_embedding_vectors_by_artifact(
    canary: &Value,
) -> BTreeMap<String, BTreeMap<String, Vec<f32>>> {
    canary
        .get("embedding_vectors")
        .and_then(Value::as_object)
        .into_iter()
        .flat_map(|object| object.iter())
        .filter_map(|(artifact_name, value)| {
            let prompts = value.as_object()?;
            let prompts = prompts
                .iter()
                .filter_map(|(prompt_id, raw_vector)| {
                    let vector = raw_vector
                        .as_array()?
                        .iter()
                        .map(|value| {
                            value.as_f64().and_then(|value| {
                                value
                                    .is_finite()
                                    .then_some(value as f32)
                                    .filter(|value| value.is_finite())
                            })
                        })
                        .collect::<Option<Vec<_>>>()?;
                    (!vector.is_empty()).then_some((prompt_id.clone(), vector))
                })
                .collect::<BTreeMap<_, _>>();
            (!prompts.is_empty()).then(|| (artifact_name.clone(), prompts))
        })
        .collect()
}

fn canary_transcripts_by_artifact(canary: &Value) -> BTreeMap<String, BTreeMap<String, String>> {
    canary
        .get("transcripts")
        .and_then(Value::as_object)
        .into_iter()
        .flat_map(|object| object.iter())
        .filter_map(|(artifact_name, value)| {
            let prompts = value.as_object()?;
            let prompts = prompts
                .iter()
                .filter_map(|(prompt_id, transcript)| {
                    transcript
                        .as_str()
                        .filter(|transcript| !transcript.trim().is_empty())
                        .map(|transcript| (prompt_id.clone(), transcript.to_owned()))
                })
                .collect::<BTreeMap<_, _>>();
            (!prompts.is_empty()).then(|| (artifact_name.clone(), prompts))
        })
        .collect()
}

fn canary_audio_fingerprints_by_artifact(
    canary: &Value,
) -> BTreeMap<String, BTreeMap<String, String>> {
    canary
        .get("audio_fingerprints")
        .and_then(Value::as_object)
        .into_iter()
        .flat_map(|object| object.iter())
        .filter_map(|(artifact_name, value)| {
            let prompts = value.as_object()?;
            let prompts = prompts
                .iter()
                .filter_map(|(prompt_id, fingerprint)| {
                    fingerprint
                        .as_str()
                        .filter(|fingerprint| is_hex_len(fingerprint, 64))
                        .map(|fingerprint| (prompt_id.clone(), fingerprint.to_owned()))
                })
                .collect::<BTreeMap<_, _>>();
            (!prompts.is_empty()).then(|| (artifact_name.clone(), prompts))
        })
        .collect()
}

fn aggregate_token_prefixes_for_prompts(
    prompts: &[GatewayCanaryPrompt],
    prefixes: &BTreeMap<String, Vec<i32>>,
) -> Option<String> {
    aggregate_token_prefixes_for_prompt_refs(prompts.iter(), prefixes)
}

fn aggregate_token_prefixes_for_prompt_refs<'a>(
    prompts: impl IntoIterator<Item = &'a GatewayCanaryPrompt>,
    prefixes: &BTreeMap<String, Vec<i32>>,
) -> Option<String> {
    let mut prompt_fingerprints = Vec::new();
    for prompt in prompts {
        let tokens = prefixes.get(&prompt.id)?;
        let fingerprint = token_fingerprint(tokens.iter().copied()).digest;
        prompt_fingerprints.push((prompt.id.as_str(), fingerprint));
    }
    Some(aggregate_canary_fingerprints(
        prompt_fingerprints
            .iter()
            .map(|(prompt_id, fingerprint)| (*prompt_id, fingerprint.as_str())),
    ))
}

fn embedded_canary_sets() -> BTreeMap<String, Vec<GatewayCanaryPrompt>> {
    [
        EMBEDDED_CANARY_DEV_V1,
        EMBEDDED_CANARY_LAUNCH_V1,
        EMBEDDED_CANARY_LAUNCH_V2,
        EMBEDDED_CANARY_IMAGE_LAUNCH_V1,
        EMBEDDED_CANARY_EMBEDDING_LAUNCH_V1,
        EMBEDDED_CANARY_TTS_LAUNCH_V1,
    ]
    .into_iter()
    .filter_map(|raw| serde_json::from_str::<CanarySetDocument>(raw).ok())
    .map(|doc| (doc.set_id.clone(), gateway_canary_prompts(doc)))
    .collect()
}

fn gateway_canary_prompts(doc: CanarySetDocument) -> Vec<GatewayCanaryPrompt> {
    doc.prompts
        .into_iter()
        .map(|prompt| GatewayCanaryPrompt {
            id: prompt.id,
            messages: prompt.messages,
            tools: prompt.tools,
            specialities: prompt.specialities,
            max_tokens: prompt.max_tokens.unwrap_or(64).max(1),
            temperature: prompt.temperature,
            top_p: prompt.top_p,
            top_k: prompt.top_k,
            min_p: prompt.min_p,
            repeat_penalty: prompt.repeat_penalty,
            frequency_penalty: prompt.frequency_penalty,
            presence_penalty: prompt.presence_penalty,
            prompt: prompt.prompt,
            input: prompt.input,
            audio_b64: prompt.audio_b64,
            content_type: prompt.content_type,
            filename: prompt.filename,
            language: prompt.language,
            voice: prompt.voice,
            response_format: prompt.response_format,
            size: prompt.size,
            steps: prompt.steps,
            cfg_scale: prompt.cfg_scale,
            seed: prompt.seed,
        })
        .collect()
}

fn provider_table_from_models(models: &[GatewayModel], rules_ver: u64) -> ProviderTable {
    let mut table = ProviderTable::new();
    for model in models {
        for candidate in &model.mayhem.route_candidates {
            table.upsert_contract(contract_snapshot_for_route(model, candidate, rules_ver));
        }
    }
    table
}

fn seed_dev_fallback_heartbeats(
    provider_table: &Arc<Mutex<ProviderTable>>,
    models: &[GatewayModel],
) {
    let now = now_millis_u64();
    let mut table = provider_table.lock_recover("provider table");
    for model in models {
        for candidate in &model.mayhem.route_candidates {
            table.upsert_fallback_heartbeat(heartbeat_for_route(model, candidate, now), now);
        }
    }
}

fn contract_snapshot_for_route(
    model: &GatewayModel,
    candidate: &GatewayRouteCandidate,
    rules_ver: u64,
) -> ContractProviderSnapshot {
    let price = route_price_ref_au(model, Some(candidate));
    ContractProviderSnapshot {
        provider: candidate.provider.clone(),
        provider_status: Some("active".to_owned()),
        enclave_id: candidate.enclave_id.clone(),
        model_id: model.id.clone(),
        room_id: candidate.room_id.clone(),
        consent_ver: rules_ver,
        reputation: f64::from(candidate.reputation_bps.min(10_000)) / 10_000.0,
        price_ver: price.ver,
        rate_map: price.rate_map.clone(),
        per_req_au: price.per_req_au,
        min_session_au: price.min_session_au,
        ref_rate_map: price.rate_map.clone(),
        probation: candidate.probation.clone(),
        caps: heartbeat_caps_for_route(model, candidate),
        attestation_head: Some(candidate.binary_hash.clone()),
        hardware_fingerprint: candidate.hardware_fingerprint.clone(),
        device_key: candidate.device_key.clone(),
    }
}

fn heartbeat_for_route(
    model: &GatewayModel,
    candidate: &GatewayRouteCandidate,
    now_millis: u64,
) -> ProviderHeartbeat {
    let price = route_price_ref_au(model, Some(candidate));
    ProviderHeartbeat {
        t: "hb".to_owned(),
        v: crate::HEARTBEAT_SCHEMA_VERSION,
        contract_version: CONTRACT_VERSION,
        provider: candidate.provider.clone(),
        enclave_id: candidate.enclave_id.clone(),
        model_id: model.id.clone(),
        room_id: candidate.room_id.clone(),
        sat: 0.0,
        slots: HeartbeatSlots {
            active: 0,
            active_requests: 0,
            max: 1,
        },
        q: HeartbeatQueue {
            free_slots: 0,
            engine_backlog: 0,
            est_wait_ms: 0,
        },
        perf: HeartbeatPerf {
            tok_s: Some(50.0),
            ttft_ms: 150,
        },
        price_ver: price.ver,
        min_ask_au: candidate.min_ask_au,
        transport_peer: Some(candidate.provider.clone()),
        identity_anchor: route_identity_anchor(candidate),
        accepting_new: true,
        caps: heartbeat_caps_for_route(model, candidate),
        att: HeartbeatAttestation {
            epoch: 1,
            head: candidate.binary_hash.clone(),
        },
        ts: now_millis / 1000,
        nonce: blake3_hex(
            format!(
                "route:{}:{}:{}:{now_millis}",
                candidate.provider, candidate.enclave_id, candidate.room_id
            )
            .as_bytes(),
        ),
        sig: String::new(),
    }
}

fn route_identity_anchor(candidate: &GatewayRouteCandidate) -> Option<String> {
    candidate
        .device_key
        .as_deref()
        .map(|value| format!("device:{}", value.to_ascii_lowercase()))
        .or_else(|| {
            candidate
                .hardware_fingerprint
                .as_deref()
                .map(|value| format!("fingerprint:{}", value.to_ascii_lowercase()))
        })
}

fn heartbeat_caps_from_model(
    caps: &ModelCaps,
    modalities: &[String],
    specialities: &[ModelSpecialityDescriptor],
) -> HeartbeatCaps {
    HeartbeatCaps {
        tools: caps.tools,
        json: caps.json,
        ctx: caps.ctx,
        vision: caps.vision,
        served_modalities: modalities.to_vec(),
        modality_capacity: BTreeMap::new(),
        served_specialities: specialities
            .iter()
            .map(|descriptor| {
                (
                    descriptor.name.clone(),
                    descriptor
                        .levels
                        .iter()
                        .map(|level| level.name.clone())
                        .collect(),
                )
            })
            .collect(),
    }
}

fn heartbeat_caps_for_route(
    model: &GatewayModel,
    candidate: &GatewayRouteCandidate,
) -> HeartbeatCaps {
    let fallback = heartbeat_caps_from_model(
        &model.mayhem.caps,
        &model.mayhem.adapter.modality_set,
        &model.mayhem.adapter.specialities,
    );
    HeartbeatCaps {
        tools: candidate
            .caps
            .get("tools")
            .and_then(Value::as_bool)
            .unwrap_or(fallback.tools),
        json: candidate
            .caps
            .get("json")
            .and_then(Value::as_bool)
            .unwrap_or(fallback.json),
        ctx: candidate
            .served_ctx
            .filter(|ctx| *ctx > 0)
            .or_else(|| {
                candidate
                    .caps
                    .get("ctx")
                    .or_else(|| candidate.caps.get("ctx_max"))
                    .and_then(Value::as_u64)
                    .and_then(|ctx| u32::try_from(ctx).ok())
            })
            .unwrap_or(fallback.ctx),
        vision: candidate
            .caps
            .get("vision")
            .and_then(Value::as_bool)
            .unwrap_or(fallback.vision),
        served_modalities: candidate.served_modalities.clone(),
        modality_capacity: candidate
            .caps
            .get("modality_capacity")
            .cloned()
            .and_then(|value| serde_json::from_value(value).ok())
            .unwrap_or_default(),
        served_specialities: candidate.served_specialities.clone(),
    }
}

fn route_caps_ctx(model: &GatewayModel, candidate: &GatewayRouteCandidate) -> u32 {
    heartbeat_caps_for_route(model, candidate).ctx
}

fn model_served_ctx(model: &GatewayModel) -> u32 {
    model.mayhem.caps.ctx
}

fn sanitize_gateway_models(models: Vec<GatewayModel>) -> Vec<GatewayModel> {
    models
        .into_iter()
        .filter_map(|mut model| {
            model
                .mayhem
                .route_candidates
                .retain(canonical_route_candidate);
            model.mayhem.markets.retain(canonical_market_info);
            model.mayhem.markets.sort_by(|left, right| {
                left.att_tier
                    .cmp(&right.att_tier)
                    .then_with(|| left.quant.cmp(&right.quant))
                    .then_with(|| left.ctx_bracket.cmp(&right.ctx_bracket))
                    .then_with(|| left.enclave_id.cmp(&right.enclave_id))
            });
            model.mayhem.markets.dedup_by(|left, right| {
                left.enclave_id == right.enclave_id && left.ctx_bracket == right.ctx_bracket
            });
            if !model.mayhem.route_candidates.is_empty() {
                let providers = model
                    .mayhem
                    .route_candidates
                    .iter()
                    .map(|candidate| candidate.provider.as_str())
                    .collect::<BTreeSet<_>>();
                let rooms = model
                    .mayhem
                    .route_candidates
                    .iter()
                    .map(|candidate| candidate.room_id.as_str())
                    .collect::<BTreeSet<_>>();
                model.mayhem.providers_online = providers.len().min(u32::MAX as usize) as u32;
                if model.mayhem.markets.is_empty() {
                    model.mayhem.rooms = rooms.len().min(u32::MAX as usize) as u32;
                }
            }
            if !model.mayhem.markets.is_empty() {
                let rooms = model
                    .mayhem
                    .markets
                    .iter()
                    .flat_map(|market| market.room_ids.iter().map(String::as_str))
                    .collect::<BTreeSet<_>>();
                model.mayhem.rooms = rooms.len().min(u32::MAX as usize) as u32;
            }
            if model.mayhem.source == "contract" && model.mayhem.route_candidates.is_empty() {
                model.mayhem.providers_online = 0;
            }
            if model.mayhem.source == "contract"
                && model.mayhem.route_candidates.is_empty()
                && model.mayhem.markets.is_empty()
            {
                return None;
            }
            Some(model)
        })
        .collect()
}

fn canonical_route_candidate(candidate: &GatewayRouteCandidate) -> bool {
    is_hex_len(&candidate.provider, 64)
        && is_hex_len(&candidate.enclave_id, 64)
        && is_hex_len(&candidate.room_id, 32)
        && is_hex_len(&candidate.admin_pubkey, 64)
        && is_hex_len(&candidate.artifact_root, 64)
        && candidate
            .artifact_sidecar_roots
            .values()
            .all(|root| is_hex_len(root, 64))
        && is_hex_len(&candidate.manifest_hash, 64)
        && is_hex_len(&candidate.binary_hash, 64)
}

fn canonical_market_info(market: &GatewayMarketInfo) -> bool {
    let availability_matches_routes = match market.availability.as_str() {
        "routable" => market.route_count > 0 && market.providers_online > 0,
        "no_eligible_provider_yet" => market.route_count == 0 && market.providers_online == 0,
        _ => false,
    };
    is_hex_len(&market.enclave_id, 64)
        && (1..=3).contains(&market.att_tier)
        && !market.room_ids.is_empty()
        && market
            .room_ids
            .iter()
            .all(|room_id| is_hex_len(room_id, 32))
        && market.providers_online <= market.route_count
        && market.price_ref_au.denom == "au_usd"
        && !market.price_ref_au.rate_map.is_empty()
        && availability_matches_routes
}

impl GatewaySessionError {
    pub fn new(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            retryable: false,
            before_first_output: false,
            transport_closed: false,
            wait_elapsed: false,
            clean_refusal: false,
            clean_refusal_code: None,
            partial: None,
            interrupted: None,
        }
    }

    pub fn retryable(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            retryable: true,
            before_first_output: false,
            transport_closed: false,
            wait_elapsed: false,
            clean_refusal: false,
            clean_refusal_code: None,
            partial: None,
            interrupted: None,
        }
    }

    pub fn retryable_before_output(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            retryable: true,
            before_first_output: true,
            transport_closed: false,
            wait_elapsed: false,
            clean_refusal: false,
            clean_refusal_code: None,
            partial: None,
            interrupted: None,
        }
    }

    pub fn transport_closed(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            retryable: true,
            before_first_output: false,
            transport_closed: true,
            wait_elapsed: false,
            clean_refusal: false,
            clean_refusal_code: None,
            partial: None,
            interrupted: None,
        }
    }

    fn wait_elapsed(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            retryable: true,
            before_first_output: false,
            transport_closed: false,
            wait_elapsed: true,
            clean_refusal: false,
            clean_refusal_code: None,
            partial: None,
            interrupted: None,
        }
    }

    pub fn clean_refusal(message: impl Into<String>) -> Self {
        Self::clean_refusal_with_code(message, None)
    }

    pub fn clean_refusal_with_code(message: impl Into<String>, code: Option<&str>) -> Self {
        Self {
            message: message.into(),
            retryable: true,
            before_first_output: false,
            transport_closed: false,
            wait_elapsed: false,
            clean_refusal: true,
            clean_refusal_code: code.map(str::to_owned),
            partial: None,
            interrupted: None,
        }
    }

    pub fn retryable_partial(message: impl Into<String>, partial: GatewaySessionPartial) -> Self {
        Self {
            message: message.into(),
            retryable: true,
            before_first_output: false,
            transport_closed: false,
            wait_elapsed: false,
            clean_refusal: false,
            clean_refusal_code: None,
            partial: Some(Box::new(partial)),
            interrupted: None,
        }
    }

    pub fn retryable_interrupted(
        message: impl Into<String>,
        interrupted: GatewaySessionInterrupted,
    ) -> Self {
        Self {
            message: message.into(),
            retryable: true,
            before_first_output: false,
            transport_closed: false,
            wait_elapsed: false,
            clean_refusal: false,
            clean_refusal_code: None,
            partial: None,
            interrupted: Some(Box::new(interrupted)),
        }
    }

    pub fn into_retryable(mut self) -> Self {
        self.retryable = true;
        self
    }

    fn into_retryable_before_output(mut self) -> Self {
        self.retryable = true;
        self.before_first_output = true;
        self
    }
}

impl GatewayRequestOptions {
    fn from_headers(headers: &HeaderMap) -> Result<Self, ApiError> {
        Ok(Self {
            hedge_requested: parse_x_mayhem_hedge(headers)?,
            min_att_tier: parse_x_mayhem_min_att_tier(headers)?,
            max_price_au: parse_x_mayhem_max_price_au(headers)?,
            max_wait_ms: parse_x_mayhem_max_wait_ms(headers)?,
            min_ctx: parse_x_mayhem_min_ctx(headers)?,
            quant: parse_x_mayhem_quant(headers)?,
            failover_overrides: parse_x_mayhem_failover_overrides(headers)?,
            preferred_providers: parse_x_mayhem_prefer_providers(headers)?,
            access_token: None,
        })
    }
}

fn valid_provider_pubkey(value: &str) -> bool {
    value.len() == 64 && value.as_bytes().iter().all(u8::is_ascii_hexdigit)
}

fn validate_preferred_provider_map(
    preferred_providers: &BTreeMap<String, Vec<String>>,
) -> Result<(), String> {
    for (model, providers) in preferred_providers {
        if model.trim().is_empty() {
            return Err("preferred provider model id must not be empty".to_owned());
        }
        if providers.is_empty() || providers.len() > MAX_PREFERRED_PROVIDERS_PER_MODEL {
            return Err(format!(
                "preferred provider list for {model} must contain 1..={MAX_PREFERRED_PROVIDERS_PER_MODEL} entries"
            ));
        }
        let mut seen = BTreeSet::new();
        for provider in providers {
            if !valid_provider_pubkey(provider) {
                return Err(format!(
                    "preferred provider for {model} must be a 32-byte hexadecimal public key"
                ));
            }
            if !seen.insert(provider.to_ascii_lowercase()) {
                return Err(format!(
                    "preferred provider list for {model} contains a duplicate public key"
                ));
            }
        }
    }
    Ok(())
}

fn parse_x_mayhem_prefer_providers(headers: &HeaderMap) -> Result<Option<Vec<String>>, ApiError> {
    let Some(value) = headers.get(X_MAYHEM_PREFER_PROVIDERS_HEADER) else {
        return Ok(None);
    };
    let value = value.to_str().map_err(|_| {
        ApiError::bad_request(
            "X-Mayhem-Prefer-Providers must be an ASCII comma-separated provider list",
            Some("X-Mayhem-Prefer-Providers"),
        )
    })?;
    let providers = value
        .split(',')
        .map(str::trim)
        .filter(|provider| !provider.is_empty())
        .map(str::to_ascii_lowercase)
        .collect::<Vec<_>>();
    if providers.is_empty() || providers.len() > MAX_PREFERRED_PROVIDERS_PER_MODEL {
        return Err(ApiError::bad_request(
            format!(
                "X-Mayhem-Prefer-Providers must contain 1..={MAX_PREFERRED_PROVIDERS_PER_MODEL} provider public keys"
            ),
            Some("X-Mayhem-Prefer-Providers"),
        ));
    }
    let mut seen = BTreeSet::new();
    if providers
        .iter()
        .any(|provider| !valid_provider_pubkey(provider) || !seen.insert(provider.clone()))
    {
        return Err(ApiError::bad_request(
            "X-Mayhem-Prefer-Providers requires unique 32-byte hexadecimal provider public keys",
            Some("X-Mayhem-Prefer-Providers"),
        ));
    }
    Ok(Some(providers))
}

fn parse_x_mayhem_max_wait_ms(headers: &HeaderMap) -> Result<u64, ApiError> {
    let Some(value) = headers.get(X_MAYHEM_MAX_WAIT_MS_HEADER) else {
        return Ok(DEFAULT_ROUTE_MAX_WAIT_MS);
    };
    let value = value.to_str().map_err(|_| {
        ApiError::bad_request(
            "X-Mayhem-Max-Wait-Ms must be an ASCII integer millisecond value",
            Some("X-Mayhem-Max-Wait-Ms"),
        )
    })?;
    let parsed = value.trim().parse::<u64>().map_err(|_| {
        ApiError::bad_request(
            "X-Mayhem-Max-Wait-Ms must be an integer millisecond value",
            Some("X-Mayhem-Max-Wait-Ms"),
        )
    })?;
    if parsed > MAX_ROUTE_MAX_WAIT_MS {
        return Err(ApiError::bad_request(
            "X-Mayhem-Max-Wait-Ms must be <= 60000",
            Some("X-Mayhem-Max-Wait-Ms"),
        ));
    }
    Ok(parsed)
}

fn parse_x_mayhem_max_price_au(headers: &HeaderMap) -> Result<Option<MoneyAu>, ApiError> {
    let Some(value) = headers.get(X_MAYHEM_MAX_PRICE_AU_HEADER) else {
        return Ok(None);
    };
    let value = value.to_str().map_err(|_| {
        ApiError::bad_request(
            "X-Mayhem-Max-Price-Au must be an ASCII positive integer atto-USD value",
            Some("X-Mayhem-Max-Price-Au"),
        )
    })?;
    let parsed = value.trim().parse::<MoneyAu>().map_err(|_| {
        ApiError::bad_request(
            "X-Mayhem-Max-Price-Au must be a positive integer atto-USD value",
            Some("X-Mayhem-Max-Price-Au"),
        )
    })?;
    if parsed == 0 {
        return Err(ApiError::bad_request(
            "X-Mayhem-Max-Price-Au must be greater than 0",
            Some("X-Mayhem-Max-Price-Au"),
        ));
    }
    Ok(Some(parsed))
}

fn parse_x_mayhem_min_ctx(headers: &HeaderMap) -> Result<Option<u32>, ApiError> {
    let Some(value) = headers.get(X_MAYHEM_MIN_CTX_HEADER) else {
        return Ok(None);
    };
    let value = value.to_str().map_err(|_| {
        ApiError::bad_request(
            "X-Mayhem-Min-Ctx must be an ASCII positive integer token count",
            Some("X-Mayhem-Min-Ctx"),
        )
    })?;
    let parsed = value.trim().parse::<u64>().map_err(|_| {
        ApiError::bad_request(
            "X-Mayhem-Min-Ctx must be a positive integer token count",
            Some("X-Mayhem-Min-Ctx"),
        )
    })?;
    let parsed = u32::try_from(parsed).map_err(|_| {
        ApiError::bad_request(
            "X-Mayhem-Min-Ctx must fit in a u32 token count",
            Some("X-Mayhem-Min-Ctx"),
        )
    })?;
    if parsed == 0 {
        return Err(ApiError::bad_request(
            "X-Mayhem-Min-Ctx must be greater than 0",
            Some("X-Mayhem-Min-Ctx"),
        ));
    }
    Ok(Some(parsed))
}

fn parse_x_mayhem_failover_overrides(
    headers: &HeaderMap,
) -> Result<GatewayFailoverPolicyConfig, ApiError> {
    reject_admin_controlled_timeout_header(
        headers,
        X_MAYHEM_OPEN_TIMEOUT_MS_HEADER,
        "X-Mayhem-Open-Timeout-Ms",
    )?;
    reject_admin_controlled_timeout_header(
        headers,
        X_MAYHEM_TTFT_TIMEOUT_MS_HEADER,
        "X-Mayhem-TTFT-Timeout-Ms",
    )?;
    reject_admin_controlled_timeout_header(
        headers,
        X_MAYHEM_STALL_TIMEOUT_MS_HEADER,
        "X-Mayhem-Stall-Timeout-Ms",
    )?;
    Ok(GatewayFailoverPolicyConfig {
        open_timeout_ms: None,
        ttft_timeout_ms: None,
        stall_timeout_ms: None,
        min_tok_s: parse_nonnegative_float_header(
            headers,
            X_MAYHEM_MIN_TOK_S_HEADER,
            "X-Mayhem-Min-Tok-S",
        )?,
    })
}

fn reject_admin_controlled_timeout_header(
    headers: &HeaderMap,
    key: &'static str,
    display: &'static str,
) -> Result<(), ApiError> {
    if headers.contains_key(key) {
        return Err(ApiError::bad_request(
            format!("{display} is admin catalog controlled; set model failover policy instead"),
            Some(display),
        ));
    }
    Ok(())
}

fn parse_nonnegative_float_header(
    headers: &HeaderMap,
    key: &'static str,
    display: &'static str,
) -> Result<Option<f64>, ApiError> {
    let Some(value) = headers.get(key) else {
        return Ok(None);
    };
    let value = value.to_str().map_err(|_| {
        ApiError::bad_request(
            format!("{display} must be an ASCII non-negative number"),
            Some(display),
        )
    })?;
    let parsed = value.trim().parse::<f64>().map_err(|_| {
        ApiError::bad_request(
            format!("{display} must be a non-negative number"),
            Some(display),
        )
    })?;
    if !parsed.is_finite() || parsed < 0.0 {
        return Err(ApiError::bad_request(
            format!("{display} must be a finite non-negative number"),
            Some(display),
        ));
    }
    Ok(Some(parsed))
}

fn parse_x_mayhem_min_att_tier(headers: &HeaderMap) -> Result<Option<u8>, ApiError> {
    let Some(value) = headers.get(X_MAYHEM_MIN_ATT_TIER_HEADER) else {
        return Ok(None);
    };
    let value = value.to_str().map_err(|_| {
        ApiError::bad_request(
            "X-Mayhem-Min-Att-Tier must be an ASCII integer from 1 through 4",
            Some("X-Mayhem-Min-Att-Tier"),
        )
    })?;
    let value = value.trim();
    let value = value.strip_prefix('T').unwrap_or(value);
    let tier = value.parse::<u8>().map_err(|_| {
        ApiError::bad_request(
            "X-Mayhem-Min-Att-Tier must be an integer from 1 through 4",
            Some("X-Mayhem-Min-Att-Tier"),
        )
    })?;
    if (1..=4).contains(&tier) {
        Ok(Some(tier))
    } else {
        Err(ApiError::bad_request(
            "X-Mayhem-Min-Att-Tier must be between 1 and 4",
            Some("X-Mayhem-Min-Att-Tier"),
        ))
    }
}

fn parse_x_mayhem_quant(headers: &HeaderMap) -> Result<Option<String>, ApiError> {
    let Some(value) = headers.get(X_MAYHEM_QUANT_HEADER) else {
        return Ok(None);
    };
    let value = value.to_str().map_err(|_| {
        ApiError::bad_request(
            "X-Mayhem-Quant must be an ASCII quant bucket",
            Some("X-Mayhem-Quant"),
        )
    })?;
    normalize_quant_bucket(value)
        .map(Some)
        .map_err(|message| ApiError::bad_request(message, Some("X-Mayhem-Quant")))
}

fn normalize_quant_bucket(value: &str) -> Result<String, String> {
    let normalized = value.trim().to_ascii_lowercase().replace('_', "-");
    if normalized.is_empty() {
        return Err("X-Mayhem-Quant must not be empty".to_owned());
    }
    if matches!(
        normalized.as_str(),
        "unknown" | "fp32" | "fp16" | "bf16" | "fp8" | "nvfp4" | "int8" | "int4"
    ) {
        return Ok(normalized);
    }
    let inferred = quant_bucket_from_descriptor(&normalized);
    if inferred != DEFAULT_QUANT_BUCKET {
        return Ok(inferred);
    }
    Err(
        "X-Mayhem-Quant must be one of fp32, fp16, bf16, fp8, nvfp4, int8, int4, unknown"
            .to_owned(),
    )
}

fn parse_x_mayhem_hedge(headers: &HeaderMap) -> Result<bool, ApiError> {
    let Some(value) = headers.get(X_MAYHEM_HEDGE_HEADER) else {
        return Ok(false);
    };
    let value = value.to_str().map_err(|_| {
        ApiError::bad_request(
            "X-Mayhem-Hedge must be an ASCII header value of 0 or 1",
            Some("X-Mayhem-Hedge"),
        )
    })?;
    if x_mayhem_hedge_requested(Some(value)) {
        return Ok(true);
    }
    if value.trim() == "0" {
        return Ok(false);
    }
    Err(ApiError::bad_request(
        "X-Mayhem-Hedge must be 1 to request hedging or 0 to disable it",
        Some("X-Mayhem-Hedge"),
    ))
}

