fn throughput_floor_retry_message(
    result: &GatewaySessionResult,
    failover: &GatewayFailoverInvocation,
) -> Option<String> {
    let min_tok_s = failover.min_tok_s?;
    let tok_s = result.quality.and_then(|quality| quality.tok_s)?;
    (tok_s < min_tok_s)
        .then(|| format!("provider throughput {tok_s:.2} tok/s below floor {min_tok_s:.2} tok/s"))
}

fn observation_sample_from_floor_failure(
    result: &GatewaySessionResult,
    elapsed: Duration,
) -> ProviderObservationSample {
    let mut sample = observation_sample_from_success(result, elapsed);
    sample.error = true;
    sample
}

fn observation_sample_from_error(elapsed: Duration) -> ProviderObservationSample {
    ProviderObservationSample {
        ttft_ms: duration_millis_u64(elapsed).max(1),
        tok_s: None,
        error: true,
    }
}

fn redispatch_request_with_partials(
    original: &ChatCompletionRequest,
    partials: &[GatewaySessionPartial],
) -> ChatCompletionRequest {
    let mut request = original.clone();
    let prefix = partial_text(partials);
    if !prefix.is_empty() {
        request.messages.push(ChatMessage {
            role: "assistant".to_owned(),
            content: json!(prefix),
            name: None,
            extra: BTreeMap::new(),
        });
        request.messages.push(ChatMessage {
            role: "user".to_owned(),
            content: json!(
                "Continue from the previous assistant message. Do not repeat text already written."
            ),
            name: None,
            extra: BTreeMap::new(),
        });
    }
    if let Some(max_tokens) = request.max_tokens {
        let delivered = partials
            .iter()
            .map(|partial| partial.output.usage.completion_tokens)
            .sum::<u64>();
        request.max_tokens = Some(
            max_tokens
                .saturating_sub(u32::try_from(delivered).unwrap_or(u32::MAX))
                .max(1),
        );
    }
    request
}

fn stitch_partials_into_result(
    result: &mut GatewaySessionResult,
    partials: &[GatewaySessionPartial],
) {
    let prefix = partial_text(partials);
    if !prefix.is_empty() && result.output.tool_calls.is_empty() {
        let suffix = result.output.content.take().unwrap_or_default();
        result.output.content = Some(format!("{prefix}{suffix}"));
    }
    let partial_completion = partials
        .iter()
        .map(|partial| partial.output.usage.completion_tokens)
        .sum::<u64>();
    result.output.usage.completion_tokens = result
        .output
        .usage
        .completion_tokens
        .saturating_add(partial_completion);
    result.output.usage.total_tokens = result
        .output
        .usage
        .prompt_tokens
        .saturating_add(result.output.usage.completion_tokens);
    let mut token_ids = partials
        .iter()
        .flat_map(|partial| partial.token_ids.iter().copied())
        .collect::<Vec<_>>();
    token_ids.extend(result.token_ids.iter().copied());
    result.token_ids = token_ids;
}

fn partial_text(partials: &[GatewaySessionPartial]) -> String {
    partials
        .iter()
        .filter_map(|partial| partial.output.content.as_deref())
        .collect::<String>()
}

fn eligible_route_candidates<'a>(
    model: &'a GatewayModel,
    min_att_tier: Option<u8>,
    quant: Option<&str>,
    rail: &str,
) -> Vec<&'a GatewayRouteCandidate> {
    model
        .mayhem
        .route_candidates
        .iter()
        .filter(|candidate| {
            candidate
                .accepted_rails
                .iter()
                .any(|candidate_rail| candidate_rail == rail)
                && min_att_tier
                    .map(|min_tier| candidate.att_tier >= min_tier)
                    .unwrap_or(true)
                && quant
                    .map(|quant| candidate.quant.eq_ignore_ascii_case(quant))
                    .unwrap_or(true)
        })
        .collect()
}

async fn build_completion(
    state: SharedState,
    request: CompletionRequest,
    raw_request: Value,
    options: GatewayRequestOptions,
) -> Result<ChatResponse, ApiError> {
    let wants_stream = request.stream;
    let mut chat = completion_chat_request(request, raw_request)?;
    chat.stream = false;
    let response = build_chat_completion(state, chat, options).await?;
    let ChatResponse::Json(response) = response else {
        return Err(ApiError::bad_gateway(
            "completion adapter expected a non-streaming provider result",
            Some("model"),
        ));
    };
    let completion = completion_response_from_chat(response)?;
    if wants_stream {
        Ok(ChatResponse::Sse(vec![completion]))
    } else {
        Ok(ChatResponse::Json(completion))
    }
}

fn completion_chat_request(
    request: CompletionRequest,
    raw_request: Value,
) -> Result<ChatCompletionRequest, ApiError> {
    let prompt = prompt_to_text(&request.prompt);
    if prompt.is_empty() {
        return Err(ApiError::bad_request(
            "prompt must not be empty",
            Some("prompt"),
        ));
    }
    Ok(ChatCompletionRequest {
        model: request.model,
        messages: vec![ChatMessage {
            role: "user".to_owned(),
            content: json!(prompt),
            name: None,
            extra: BTreeMap::new(),
        }],
        user: request.user,
        metadata: BTreeMap::new(),
        stream: false,
        stream_options: None,
        tools: None,
        tool_choice: None,
        parallel_tool_calls: None,
        response_format: None,
        temperature: request.temperature,
        top_p: request.top_p,
        top_k: request.top_k,
        min_p: request.min_p,
        repeat_penalty: None,
        frequency_penalty: request.frequency_penalty,
        presence_penalty: request.presence_penalty,
        seed: request.seed,
        stop: request.stop,
        max_tokens: request.max_tokens,
        max_completion_tokens: None,
        reasoning_effort: request.reasoning_effort,
        speciality_values: request.speciality_values,
        effective_specialities: BTreeMap::new(),
        endpoint_family: Some(mayhem_proto::ENDPOINT_OPENAI_COMPLETIONS.to_owned()),
        endpoint_request: Some(raw_request),
    })
}

fn completion_response_from_chat(mut response: Value) -> Result<Value, ApiError> {
    let choices = response
        .get_mut("choices")
        .and_then(Value::as_array_mut)
        .ok_or_else(|| ApiError::bad_gateway("chat provider returned no choices", Some("model")))?;
    for choice in choices {
        let text = choice
            .get("message")
            .and_then(|message| message.get("content"))
            .cloned()
            .unwrap_or(Value::Null);
        let tool_calls = choice
            .get("message")
            .and_then(|message| message.get("tool_calls"))
            .cloned();
        let object = choice
            .as_object_mut()
            .ok_or_else(|| ApiError::bad_gateway("chat choice was not an object", Some("model")))?;
        object.remove("message");
        object.insert(
            "text".to_owned(),
            if let Some(tool_calls) = tool_calls {
                json!({"tool_calls": tool_calls}).to_string().into()
            } else {
                text
            },
        );
        object.entry("logprobs").or_insert(Value::Null);
    }
    response["object"] = json!("text_completion");
    Ok(response)
}

async fn build_response(
    state: SharedState,
    request: ResponsesRequest,
    raw_request: Value,
    options: GatewayRequestOptions,
) -> Result<ChatResponse, ApiError> {
    let wants_stream = request.stream;
    let mut chat = responses_chat_request(request, raw_request)?;
    chat.stream = false;
    let response = build_chat_completion(state, chat, options).await?;
    let ChatResponse::Json(response) = response else {
        return Err(ApiError::bad_gateway(
            "responses adapter expected a non-streaming provider result",
            Some("model"),
        ));
    };
    let response = responses_value_from_chat(response)?;
    if wants_stream {
        Ok(ChatResponse::Sse(vec![json!({
            "type": "response.completed",
            "response": response,
        })]))
    } else {
        Ok(ChatResponse::Json(response))
    }
}

fn responses_chat_request(
    request: ResponsesRequest,
    raw_request: Value,
) -> Result<ChatCompletionRequest, ApiError> {
    let messages = responses_input_messages(&request.input)?;
    let nested_reasoning_effort = request
        .reasoning
        .as_ref()
        .and_then(|reasoning| reasoning.get("effort"))
        .and_then(Value::as_str)
        .map(str::to_owned);
    if request.reasoning_effort.is_some()
        && nested_reasoning_effort.is_some()
        && request.reasoning_effort != nested_reasoning_effort
    {
        return Err(ApiError::bad_request(
            "reasoning_effort conflicts with reasoning.effort",
            Some("reasoning_effort"),
        ));
    }
    let reasoning_effort = request.reasoning_effort.or(nested_reasoning_effort);
    let response_format = request
        .text
        .as_ref()
        .and_then(|text| text.get("format"))
        .cloned();
    Ok(ChatCompletionRequest {
        model: request.model,
        messages,
        user: request.user,
        metadata: request.metadata,
        stream: false,
        stream_options: None,
        tools: request.tools,
        tool_choice: request.tool_choice,
        parallel_tool_calls: request.parallel_tool_calls,
        response_format,
        temperature: request.temperature,
        top_p: request.top_p,
        top_k: request.top_k,
        min_p: request.min_p,
        repeat_penalty: None,
        frequency_penalty: None,
        presence_penalty: None,
        seed: None,
        stop: None,
        max_tokens: request.max_output_tokens,
        max_completion_tokens: None,
        reasoning_effort,
        speciality_values: request.speciality_values,
        effective_specialities: BTreeMap::new(),
        endpoint_family: Some(mayhem_proto::ENDPOINT_OPENAI_RESPONSES.to_owned()),
        endpoint_request: Some(raw_request),
    })
}

fn responses_input_messages(input: &Value) -> Result<Vec<ChatMessage>, ApiError> {
    match input {
        Value::String(text) if !text.trim().is_empty() => Ok(vec![ChatMessage {
            role: "user".to_owned(),
            content: json!(text),
            name: None,
            extra: BTreeMap::new(),
        }]),
        Value::Array(items) if !items.is_empty() => items
            .iter()
            .map(|item| {
                let role = item
                    .get("role")
                    .and_then(Value::as_str)
                    .filter(|role| !role.is_empty())
                    .ok_or_else(|| {
                        ApiError::bad_request(
                            "Responses input message is missing role",
                            Some("input"),
                        )
                    })?;
                let content = item.get("content").cloned().ok_or_else(|| {
                    ApiError::bad_request(
                        "Responses input message is missing content",
                        Some("input"),
                    )
                })?;
                Ok(ChatMessage {
                    role: role.to_owned(),
                    content,
                    name: item.get("name").and_then(Value::as_str).map(str::to_owned),
                    extra: item
                        .as_object()
                        .into_iter()
                        .flatten()
                        .filter(|(key, _)| !matches!(key.as_str(), "role" | "content" | "name"))
                        .map(|(key, value)| (key.clone(), value.clone()))
                        .collect(),
                })
            })
            .collect(),
        _ => Err(ApiError::bad_request(
            "input must be a non-empty string or array of message objects",
            Some("input"),
        )),
    }
}

fn responses_value_from_chat(response: Value) -> Result<Value, ApiError> {
    let id = response
        .get("id")
        .cloned()
        .unwrap_or_else(|| json!(make_id("resp")));
    let model = response.get("model").cloned().unwrap_or(Value::Null);
    let created_at = response
        .get("created")
        .cloned()
        .unwrap_or_else(|| json!(now_secs()));
    let choice = response
        .get("choices")
        .and_then(Value::as_array)
        .and_then(|choices| choices.first())
        .ok_or_else(|| ApiError::bad_gateway("chat provider returned no choices", Some("model")))?;
    let message = choice.get("message").cloned().unwrap_or_else(|| json!({}));
    let text = message.get("content").cloned().unwrap_or(Value::Null);
    let mut output_content = vec![json!({
        "type": "output_text",
        "text": text,
        "annotations": [],
    })];
    if let Some(tool_calls) = message.get("tool_calls").and_then(Value::as_array) {
        output_content.extend(tool_calls.iter().map(|call| {
            json!({
                "type": "function_call",
                "call_id": call.get("id").cloned().unwrap_or(Value::Null),
                "name": call.get("function").and_then(|function| function.get("name")).cloned().unwrap_or(Value::Null),
                "arguments": call.get("function").and_then(|function| function.get("arguments")).cloned().unwrap_or(Value::Null),
            })
        }));
    }
    let usage = response.get("usage").cloned().unwrap_or_else(|| json!({}));
    Ok(json!({
        "id": id,
        "object": "response",
        "created_at": created_at,
        "status": "completed",
        "model": model,
        "output": [{
            "id": make_id("msg"),
            "type": "message",
            "status": "completed",
            "role": "assistant",
            "content": output_content,
        }],
        "usage": {
            "input_tokens": usage.get("prompt_tokens").cloned().unwrap_or_else(|| json!(0)),
            "output_tokens": usage.get("completion_tokens").cloned().unwrap_or_else(|| json!(0)),
            "total_tokens": usage.get("total_tokens").cloned().unwrap_or_else(|| json!(0)),
        },
        "mayhem": response.get("mayhem").cloned().unwrap_or_else(|| json!({})),
    }))
}
async fn build_embedding(
    state: &GatewayState,
    request: EmbeddingRequest,
    options: GatewayRequestOptions,
) -> Result<Value, ApiError> {
    let model = require_model(state, &request.model)?;
    if !model_supports_embeddings(&model) {
        return Err(ApiError::bad_request(
            "model does not support embeddings",
            Some("model"),
        ));
    }
    let inputs = embedding_input_texts(&request)?;
    let encoding_format = embedding_encoding_format(&request)?;
    let id = make_id("embd");
    let created = now_secs();
    let GatewayEmbeddingRun {
        result:
            GatewayEmbeddingResult {
                output,
                backend,
                direct_session,
                provider_receipt,
                quality,
            },
        invocation,
        metering_inputs,
        metering_output,
    } = run_embedding_with_route_retry(state, &model, &request, &inputs, options).await?;
    let receipt = if state.dev_session_shim {
        None
    } else {
        let receipt = state.meter_embedding_session(
            &model,
            &metering_inputs,
            &metering_output,
            &invocation,
            provider_receipt.as_ref(),
        )?;
        state
            .maybe_run_canary_probe_after_session(&model, &invocation)
            .await;
        Some(receipt_summary(&receipt))
    };
    let data = output
        .embeddings
        .iter()
        .enumerate()
        .map(|(index, embedding)| {
            json!({
                "object": "embedding",
                "index": index,
                "embedding": embedding_response_value(embedding, encoding_format),
            })
        })
        .collect::<Vec<_>>();
    Ok(json!({
        "id": id,
        "object": "list",
        "created": created,
        "model": model.id,
        "data": data,
        "usage": {
            "prompt_tokens": output.usage.prompt_tokens,
            "total_tokens": output.usage.total_tokens,
        },
        "mayhem": {
            "backend": backend,
            "direct_session": direct_session,
            "billable": !state.dev_session_shim,
            "dev_session": state.dev_session_shim,
            "quality": quality.map(|quality| json!({
                "ttft_ms": quality.ttft_ms,
                "tok_s": quality.tok_s,
            })),
            "receipt": receipt,
        },
    }))
}

