fn canary_chat_request(
    model: &GatewayModel,
    prompt: &GatewayCanaryPrompt,
    seed: i64,
) -> Result<ChatCompletionRequest, ApiError> {
    let mut request = ChatCompletionRequest {
        model: model.id.clone(),
        messages: prompt.messages.clone(),
        user: None,
        metadata: BTreeMap::new(),
        stream: true,
        stream_options: Some(StreamOptions {
            include_usage: Some(true),
        }),
        tools: prompt.tools.clone(),
        tool_choice: None,
        parallel_tool_calls: None,
        response_format: None,
        temperature: prompt.temperature,
        top_p: prompt.top_p,
        top_k: prompt.top_k,
        min_p: prompt.min_p,
        repeat_penalty: prompt.repeat_penalty,
        frequency_penalty: prompt.frequency_penalty,
        presence_penalty: prompt.presence_penalty,
        seed: Some(prompt.seed.unwrap_or(seed)),
        stop: None,
        max_tokens: Some(prompt.max_tokens.max(1)),
        max_completion_tokens: None,
        reasoning_effort: prompt.specialities.get("reasoning_effort").cloned(),
        speciality_values: prompt
            .specialities
            .iter()
            .filter(|(name, _)| name.as_str() != "reasoning_effort")
            .map(|(name, level)| (name.clone(), json!(level)))
            .collect(),
        effective_specialities: BTreeMap::new(),
        endpoint_family: None,
        endpoint_request: None,
    };
    apply_model_sampling_defaults(model, &mut request)?;
    apply_model_speciality_defaults(model, &mut request)?;
    Ok(request)
}

