    #[derive(Debug)]
    struct PartialThenSuccessBackend {
        attempts: Arc<Mutex<Vec<Vec<ChatMessage>>>>,
        providers: Arc<Mutex<Vec<String>>>,
    }

    impl GatewaySessionBackend for PartialThenSuccessBackend {
        fn name(&self) -> &str {
            "test-partial-then-success"
        }

        fn run_chat<'a>(
            &'a self,
            model: &'a GatewayModel,
            request: &'a ChatCompletionRequest,
            invocation: &'a GatewaySessionInvocation,
        ) -> GatewaySessionFuture<'a> {
            Box::pin(async move {
                let attempt = {
                    self.providers
                        .lock()
                        .expect("providers lock")
                        .push(invocation.provider_pubkey.clone().unwrap_or_default());
                    let mut attempts = self.attempts.lock().expect("attempts lock");
                    attempts.push(request.messages.clone());
                    attempts.len()
                };
                if attempt == 1 {
                    let output = ChatOutput {
                        content: Some("hello ".to_owned()),
                        tool_calls: Vec::new(),
                        artifacts: Vec::new(),
                        finish_reason: "interrupted".to_owned(),
                        usage: Usage {
                            prompt_tokens: rough_tokens(&chat_prompt_text(request)),
                            completion_tokens: 1,
                            total_tokens: rough_tokens(&chat_prompt_text(request)) + 1,
                        },
                    };
                    let provider_receipt = test_provider_receipt_with_finality(
                        model, request, &output, invocation, 1, false,
                    );
                    return Err(GatewaySessionError::retryable_partial(
                        "simulated mid-stream stall after checkpoint",
                        GatewaySessionPartial {
                            output,
                            provider_receipt,
                            token_ids: vec![11],
                            quality: Some(GatewaySessionQuality {
                                ttft_ms: 25,
                                tok_s: Some(20.0),
                            }),
                            reason: "mid_stream_stall".to_owned(),
                            redispatch_mode: RedispatchMode::FullMessageHistoryClientSide,
                        },
                    ));
                }

                assert!(
                    request.messages.iter().any(|message| {
                        message.role == "assistant" && message.content == json!("hello ")
                    }),
                    "redispatch request should include the checkpointed assistant prefix"
                );
                let output = ChatOutput {
                    content: Some("world".to_owned()),
                    tool_calls: Vec::new(),
                    artifacts: Vec::new(),
                    finish_reason: "stop".to_owned(),
                    usage: Usage {
                        prompt_tokens: rough_tokens(&chat_prompt_text(request)),
                        completion_tokens: 1,
                        total_tokens: rough_tokens(&chat_prompt_text(request)) + 1,
                    },
                };
                Ok(GatewaySessionResult {
                    output: output.clone(),
                    backend: self.name().to_owned(),
                    direct_session: true,
                    provider_receipt: Some(test_provider_receipt(
                        model, request, &output, invocation,
                    )),
                    token_ids: vec![22],
                    quality: Some(GatewaySessionQuality {
                        ttft_ms: 30,
                        tok_s: Some(25.0),
                    }),
                })
            })
        }
    }

    #[derive(Debug)]
    struct ExactContextPartialThenSuccessBackend {
        providers: Arc<Mutex<Vec<String>>>,
        served_contexts: Arc<Mutex<Vec<u32>>>,
    }

    impl GatewaySessionBackend for ExactContextPartialThenSuccessBackend {
        fn name(&self) -> &str {
            "test-exact-context-partial-then-success"
        }

        fn run_chat<'a>(
            &'a self,
            model: &'a GatewayModel,
            request: &'a ChatCompletionRequest,
            invocation: &'a GatewaySessionInvocation,
        ) -> GatewaySessionFuture<'a> {
            Box::pin(async move {
                let attempt = {
                    self.providers
                        .lock()
                        .expect("providers lock")
                        .push(invocation.provider_pubkey.clone().unwrap_or_default());
                    self.served_contexts
                        .lock()
                        .expect("served contexts lock")
                        .push(invocation.served_ctx);
                    self.providers.lock().expect("providers lock").len()
                };
                if attempt == 1 {
                    let output = ChatOutput {
                        content: Some("checkpoint ".to_owned()),
                        tool_calls: Vec::new(),
                        artifacts: Vec::new(),
                        finish_reason: "interrupted".to_owned(),
                        usage: Usage {
                            prompt_tokens: 7_700,
                            completion_tokens: 200,
                            total_tokens: 7_900,
                        },
                    };
                    let provider_receipt = test_provider_receipt_with_finality(
                        model, request, &output, invocation, 1, false,
                    );
                    return Err(GatewaySessionError::retryable_partial(
                        "simulated checkpoint after exact context accounting",
                        GatewaySessionPartial {
                            output,
                            provider_receipt,
                            token_ids: vec![11],
                            quality: None,
                            reason: "mid_stream_stall".to_owned(),
                            redispatch_mode: RedispatchMode::FullMessageHistoryClientSide,
                        },
                    ));
                }

                let prompt_tokens = rough_tokens(&chat_prompt_text(request));
                let output = ChatOutput {
                    content: Some("continued".to_owned()),
                    tool_calls: Vec::new(),
                    artifacts: Vec::new(),
                    finish_reason: "stop".to_owned(),
                    usage: Usage {
                        prompt_tokens,
                        completion_tokens: 1,
                        total_tokens: prompt_tokens + 1,
                    },
                };
                Ok(GatewaySessionResult {
                    output: output.clone(),
                    backend: self.name().to_owned(),
                    direct_session: true,
                    provider_receipt: Some(test_provider_receipt(
                        model, request, &output, invocation,
                    )),
                    token_ids: vec![22],
                    quality: None,
                })
            })
        }
    }

