    #[tokio::test]
    async fn context_capacity_failure_is_plain_and_does_not_touch_provider_reputation() {
        let mut model = test_routed_model(1);
        model.mayhem.route_candidates[0].served_ctx = Some(8_192);
        let providers = Arc::new(Mutex::new(Vec::new()));
        let state = test_gateway_state_from_models(vec![model.clone()]).with_session_backend(
            Arc::new(SuccessBackend {
                providers: providers.clone(),
            }),
        );
        let mut request = test_chat_request(&model.id);
        request.messages[0].content = json!("word ".repeat(9_000));
        request.max_tokens = Some(64);
        let options = GatewayRequestOptions {
            max_wait_ms: 0,
            ..GatewayRequestOptions::default()
        };

        let err = match run_chat_with_route_retry(&state, &model, &request, options).await {
            Ok(_) => panic!("an 8k provider cannot hold this conversation"),
            Err(err) => err,
        };

        assert_eq!(err.status, StatusCode::SERVICE_UNAVAILABLE);
        assert!(err.message.contains("needs at least 9064 context tokens"));
        assert!(err.message.contains(&model.id));
        assert!(!err.message.contains("PromptTooLong"));
        assert!(!err.message.contains("attempt"));
        assert!(providers.lock().expect("providers lock").is_empty());
        assert!(state.reputation_events().is_empty());
    }

    #[tokio::test]
    async fn partial_receipt_raises_context_floor_before_failover_routing() {
        let mut model = test_routed_model(3);
        model.mayhem.caps.ctx = 262_144;
        model.mayhem.route_candidates[0].served_ctx = Some(8_192);
        model.mayhem.route_candidates[0].reputation_bps = 10_000;
        model.mayhem.route_candidates[1].served_ctx = Some(8_192);
        model.mayhem.route_candidates[1].reputation_bps = 9_000;
        model.mayhem.route_candidates[2].served_ctx = Some(262_144);
        model.mayhem.route_candidates[2].reputation_bps = 1_000;
        let skipped_small_key = route_key(&model.mayhem.route_candidates[1]);
        let providers = Arc::new(Mutex::new(Vec::new()));
        let served_contexts = Arc::new(Mutex::new(Vec::new()));
        let state = test_gateway_state_from_models(vec![model.clone()]).with_session_backend(
            Arc::new(ExactContextPartialThenSuccessBackend {
                providers: providers.clone(),
                served_contexts: served_contexts.clone(),
            }),
        );
        let mut request = test_chat_request(&model.id);
        request.messages[0].content = json!("word ".repeat(7_600));
        request.max_tokens = Some(512);
        let options = GatewayRequestOptions {
            max_wait_ms: 0,
            ..GatewayRequestOptions::default()
        };

        let run = run_chat_with_route_retry(&state, &model, &request, options)
            .await
            .expect("the exact receipt floor should reroute to the 256k provider");

        assert_eq!(
            run.result.output.content.as_deref(),
            Some("checkpoint continued")
        );
        assert_eq!(
            providers.lock().expect("providers lock").as_slice(),
            &[
                model.mayhem.route_candidates[0].provider.clone(),
                model.mayhem.route_candidates[2].provider.clone(),
            ]
        );
        assert_eq!(
            served_contexts
                .lock()
                .expect("served contexts lock")
                .as_slice(),
            &[8_192, 262_144]
        );
        let skipped_observation = state
            .provider_table
            .lock_recover("provider table")
            .entries(now_millis_u64())
            .into_iter()
            .find(|entry| entry.key == skipped_small_key)
            .expect("skipped small provider remains in the table")
            .observed;
        assert_eq!(skipped_observation.samples, 0);
        assert_eq!(state.receipts().len(), 1);
    }

    #[tokio::test]
    async fn route_retry_records_partial_receipt_and_redispatches_remaining_history() {
        let model = test_routed_model(2);
        let attempts = Arc::new(Mutex::new(Vec::new()));
        let providers = Arc::new(Mutex::new(Vec::new()));
        let state = test_gateway_state_from_models(vec![model.clone()]).with_session_backend(
            Arc::new(PartialThenSuccessBackend {
                attempts: attempts.clone(),
                providers: providers.clone(),
            }),
        );
        let mut request = test_chat_request(&model.id);
        request.max_tokens = Some(8);

        let run =
            run_chat_with_route_retry(&state, &model, &request, GatewayRequestOptions::default())
                .await
                .expect("redispatch should recover");

        assert_eq!(run.result.output.content.as_deref(), Some("hello world"));
        assert_eq!(run.result.output.usage.completion_tokens, 2);
        assert_eq!(run.result.token_ids, vec![11, 22]);
        assert_eq!(run.metering_output.content.as_deref(), Some("world"));
        assert!(run
            .metering_request
            .messages
            .iter()
            .any(|message| message.role == "assistant" && message.content == json!("hello ")));
        assert_eq!(attempts.lock().expect("attempts lock").len(), 2);
        let providers = providers.lock().expect("providers lock").clone();
        assert_eq!(providers.len(), 2);
        let failed_provider = &providers[0];
        let post_failure_order =
            ordered_route_candidates_for_request_with_seed(&state, &model, &request, None, 0xfeed);
        assert!(!post_failure_order
            .iter()
            .any(|candidate| &candidate.provider == failed_provider));

        let partial_receipts = state.receipts();
        assert_eq!(partial_receipts.len(), 1);
        assert!(!partial_receipts[0].receipt.body.final_receipt);
        assert_eq!(partial_receipts[0].receipt.body.usage.output_tokens(), 1);

        state
            .meter_chat_session(
                &model,
                &run.metering_request,
                &run.metering_output,
                &run.invocation,
                run.result.provider_receipt.as_ref(),
            )
            .expect("final receipt should validate against redispatch attempt only");
        let receipts = state.receipts();
        assert_eq!(receipts.len(), 2);
        assert!(receipts[1].receipt.body.final_receipt);
        assert_eq!(receipts[1].receipt.body.usage.output_tokens(), 1);
    }

    #[tokio::test]
    async fn accept_then_close_before_output_reroutes_and_demotes_without_a_receipt() {
        let model = test_routed_model(2);
        let providers = Arc::new(Mutex::new(Vec::new()));
        let state = test_gateway_state_from_models(vec![model.clone()]).with_session_backend(
            Arc::new(AcceptThenCloseThenSuccessBackend {
                providers: providers.clone(),
            }),
        );
        let request = test_chat_request(&model.id);

        let run =
            run_chat_with_route_retry(&state, &model, &request, GatewayRequestOptions::default())
                .await
                .expect("an accepted session that closes before output should fail over");

        assert_eq!(
            run.result.output.content.as_deref(),
            Some("recovered after close")
        );
        let providers = providers.lock().expect("providers lock").clone();
        assert_eq!(providers.len(), 2);
        assert_ne!(providers[0], providers[1]);
        let failed_route = model
            .mayhem
            .route_candidates
            .iter()
            .find(|candidate| candidate.provider == providers[0])
            .expect("failed provider route");
        assert!(state.route_provider_in_cooloff(failed_route, now_millis_u64()));
        let failed_entry = state
            .provider_table
            .lock_recover("provider table")
            .entries(now_millis_u64())
            .into_iter()
            .find(|entry| entry.key.provider == providers[0])
            .expect("failed provider observation");
        assert_eq!(failed_entry.observed.samples, 1);
        assert_eq!(failed_entry.observed.consecutive_failures, 1);
        assert!(state.receipts().is_empty());
    }

    #[test]
    fn pre_output_retry_classification_requires_no_delta_and_no_receipt() {
        let watchdog = DirectSessionWatchdog::new(1_000, None, None, None, None);
        let pre_output = retryable_interrupted_direct_session_error(
            GatewaySessionError::new("provider closed"),
            "",
            Vec::new(),
            None,
            false,
            &[],
            &watchdog,
            1_001,
            "mid_stream_close",
        );
        assert!(pre_output.retryable);
        assert!(pre_output.before_first_output);
        assert!(pre_output.partial.is_none());

        let receipt_seen = retryable_interrupted_direct_session_error(
            GatewaySessionError::new("provider closed"),
            "",
            Vec::new(),
            None,
            true,
            &[],
            &watchdog,
            1_001,
            "mid_stream_close",
        );
        assert!(!receipt_seen.retryable);
        assert!(!receipt_seen.before_first_output);

        let mut after_delta = watchdog;
        after_delta.record_delta(1_001);
        let output_started = retryable_interrupted_direct_session_error(
            GatewaySessionError::new("provider closed"),
            "partial output",
            Vec::new(),
            None,
            false,
            &[],
            &after_delta,
            1_002,
            "mid_stream_close",
        );
        assert!(!output_started.retryable);
        assert!(!output_started.before_first_output);
    }

