    #[test]
    fn session_delta_refs_reassemble_large_tool_embeddings_and_token_ids() {
        let mut pending = SessionDeltaPayloadChunks::default();
        let tools = json!([
            {
                "id": "call-large-1",
                "name": "write_file",
                "arguments": json!({ "content": "x".repeat(10_000) }).to_string(),
            },
            {
                "id": "call-large-2",
                "name": "read_file",
                "arguments": r#"{"path":"README.md"}"#,
            }
        ]);
        let embeddings = json!([vec![0.25_f32; 2048], vec![0.5_f32; 2048]]);
        let token_ids = json!((0..4096).collect::<Vec<i32>>());
        let fields = [
            ("tools", tools.clone()),
            ("embeddings", embeddings.clone()),
            ("token_ids", token_ids.clone()),
        ];
        let mut manifests = BTreeMap::new();
        for (field, value) in fields {
            let (manifest, chunks) = chunk_json_payload(&value, 512).unwrap();
            for chunk in chunks {
                collect_session_delta_chunk(
                    &json!({
                        "t": "s.delta_chunk",
                        "rid": "rid-large",
                        "field": field,
                        "payload_id": manifest.blake3.clone(),
                        "chunk": chunk,
                    }),
                    &mut pending,
                )
                .unwrap();
            }
            manifests.insert(field, manifest);
        }
        let frame = json!({
            "t": "s.delta",
            "rid": "rid-large",
            "tools": null,
            "tools_ref": manifests["tools"],
            "embeddings": null,
            "embeddings_ref": manifests["embeddings"],
            "token_ids": null,
            "token_ids_ref": manifests["token_ids"],
        });

        let restored_tools = tool_calls_from_session_delta_resolving(&frame, &mut pending)
            .unwrap()
            .unwrap();
        let restored_embeddings = embeddings_from_session_delta(&frame, &mut pending)
            .unwrap()
            .unwrap();
        let restored_token_ids = token_ids_ref_from_session_delta(&frame, &mut pending)
            .unwrap()
            .unwrap();

        assert_eq!(restored_tools.len(), 2);
        assert_eq!(restored_tools[0].id, "call-large-1");
        assert_eq!(restored_tools[0].name, "write_file");
        assert_eq!(
            restored_tools[0].arguments,
            json!({ "content": "x".repeat(10_000) }).to_string()
        );
        assert_eq!(restored_tools[1].id, "call-large-2");
        assert_eq!(restored_tools[1].name, "read_file");
        assert_eq!(restored_tools[1].arguments, r#"{"path":"README.md"}"#);
        assert_eq!(restored_embeddings.len(), 2);
        assert_eq!(restored_embeddings[0].len(), 2048);
        assert_eq!(restored_token_ids.len(), 4096);
        assert!(pending.chunks.is_empty());
    }

    #[test]
    fn session_delta_sequence_rejects_replay_reordering_and_post_final_data() {
        let mut ordered = SessionDeltaSequence::default();
        ordered
            .observe(&json!({ "t": "s.delta", "i": 0, "d": "one", "fin": null }))
            .unwrap();
        ordered
            .observe(&json!({ "t": "s.delta_chunk", "i": 1 }))
            .unwrap();
        ordered
            .observe(&json!({ "t": "s.delta", "i": 2, "d": "two", "fin": "stop" }))
            .unwrap();
        assert!(ordered
            .observe(&json!({ "t": "s.delta", "i": 3, "d": "late", "fin": null }))
            .unwrap_err()
            .message
            .contains("after the final"));

        let mut replay = SessionDeltaSequence::default();
        replay
            .observe(&json!({ "t": "s.delta", "i": 0, "d": "one", "fin": null }))
            .unwrap();
        assert!(replay
            .observe(&json!({ "t": "s.delta", "i": 0, "d": "replay", "fin": null }))
            .unwrap_err()
            .message
            .contains("out of order"));

        let mut reordered = SessionDeltaSequence::default();
        assert!(reordered
            .observe(&json!({ "t": "s.delta", "i": 1, "d": "skip", "fin": null }))
            .unwrap_err()
            .message
            .contains("expected 0"));
    }

