    #[test]
    fn session_artifact_delta_collects_chunks_and_verifies_digest() {
        let bytes = b"\x89PNG mayhem image".to_vec();
        let digest = blake3_hex(&bytes);
        let mut builders = SessionArtifactCollection::default();

        collect_artifact_from_session_delta(
            &json!({
                "t": "s.delta",
                "rid": "rid-1",
                "artifact": {
                    "id": "image-1",
                    "content_type": "image/png",
                    "encoding": "hex",
                    "offset": 0,
                    "len": 4,
                    "total_len": bytes.len(),
                    "blake3": digest,
                    "data": hex::encode(&bytes[..4]),
                    "final": false,
                }
            }),
            &mut builders,
        )
        .unwrap();
        collect_artifact_from_session_delta(
            &json!({
                "t": "s.delta",
                "rid": "rid-1",
                "artifact": {
                    "id": "image-1",
                    "content_type": "image/png",
                    "encoding": "hex",
                    "offset": 4,
                    "len": bytes.len() - 4,
                    "total_len": bytes.len(),
                    "blake3": digest,
                    "data": hex::encode(&bytes[4..]),
                    "final": true,
                }
            }),
            &mut builders,
        )
        .unwrap();

        let artifacts = finish_session_artifacts(builders).unwrap();
        assert_eq!(artifacts.len(), 1);
        assert_eq!(artifacts[0].id, "image-1");
        assert_eq!(artifacts[0].content_type, "image/png");
        assert_eq!(artifacts[0].bytes, bytes);
        assert_eq!(artifacts[0].blake3, blake3_hex(&artifacts[0].bytes));
    }

    #[test]
    fn session_artifact_delta_rejects_corrupt_digest() {
        let bytes = b"not the claimed image".to_vec();
        let mut builders = SessionArtifactCollection::default();
        collect_artifact_from_session_delta(
            &json!({
                "t": "s.delta",
                "rid": "rid-1",
                "artifact": {
                    "id": "image-1",
                    "content_type": "image/png",
                    "encoding": "hex",
                    "offset": 0,
                    "len": bytes.len(),
                    "total_len": bytes.len(),
                    "blake3": "00".repeat(32),
                    "data": hex::encode(&bytes),
                    "final": true,
                }
            }),
            &mut builders,
        )
        .unwrap();

        let err = finish_session_artifacts(builders).expect_err("digest mismatch must reject");
        assert!(err.message.contains("blake3 mismatch"));
    }

    #[test]
    fn session_artifact_delta_enforces_aggregate_budget_and_finality() {
        let bytes = b"12345";
        let digest = blake3_hex(bytes);
        let mut too_large = SessionArtifactCollection {
            builders: BTreeMap::new(),
            total_bytes: 0,
            max_total_bytes: 4,
            max_artifacts: 1,
        };
        let err = collect_artifact_from_session_delta(
            &json!({
                "artifact": {
                    "id": "a",
                    "content_type": "application/octet-stream",
                    "encoding": "hex",
                    "offset": 0,
                    "len": bytes.len(),
                    "total_len": bytes.len(),
                    "blake3": digest,
                    "data": hex::encode(bytes),
                    "final": true,
                }
            }),
            &mut too_large,
        )
        .unwrap_err();
        assert!(err.message.contains("session budget"));

        let one = b"1";
        let mut finalized = SessionArtifactCollection {
            builders: BTreeMap::new(),
            total_bytes: 0,
            max_total_bytes: 16,
            max_artifacts: 1,
        };
        let frame = json!({
            "artifact": {
                "id": "a",
                "content_type": "application/octet-stream",
                "encoding": "hex",
                "offset": 0,
                "len": 1,
                "total_len": 1,
                "blake3": blake3_hex(one),
                "data": hex::encode(one),
                "final": true,
            }
        });
        collect_artifact_from_session_delta(&frame, &mut finalized).unwrap();
        assert!(collect_artifact_from_session_delta(&frame, &mut finalized)
            .unwrap_err()
            .message
            .contains("after its final"));
    }

    #[test]
    fn dashboard_money_format_preserves_sub_cent_au() {
        assert_eq!(format_au_usd(0), "$0.00");
        assert_eq!(format_au_usd(1), "$0.000000000000000001");
        assert_eq!(format_au_usd(10_000_000), "$0.00000000001");
        assert_eq!(format_au_usd(AU_PER_CENT), "$0.01");
        let price = PriceRefAu {
            denom: "au_usd".to_owned(),
            ver: 1,
            rate_map: vec![RateMapEntry {
                unit: "input_token".to_owned(),
                per_unit_au: 10_000_000,
                granularity: 1000,
            }],
            per_req_au: 0,
            min_session_au: 0,
            derivation: None,
            history: Vec::new(),
        };
        let label = dashboard_price(&price);
        assert!(label.contains("$0.00000000001 / 1000 input_token"));
        assert!(!label.contains("au/"));
    }

    #[test]
    fn dashboard_keeps_multi_unit_prices_separate_and_exposes_endpoint_families() {
        let price = PriceRefAu {
            denom: "au_usd".to_owned(),
            ver: 4,
            rate_map: vec![
                RateMapEntry {
                    unit: USAGE_IMAGE.to_owned(),
                    per_unit_au: 500,
                    granularity: 1,
                },
                RateMapEntry {
                    unit: USAGE_STEP.to_owned(),
                    per_unit_au: 2,
                    granularity: 1,
                },
            ],
            per_req_au: 0,
            min_session_au: 0,
            derivation: None,
            history: vec![json!({
                "epoch": 3,
                "ctx_bracket": "base",
                "result_price": {
                    "rate_map": [
                        {"unit": USAGE_IMAGE, "per_unit_au": "450", "granularity": 1},
                        {"unit": USAGE_STEP, "per_unit_au": "3", "granularity": 1}
                    ]
                },
                "usage": {"settled_au": "10"}
            })],
        };
        let series = dashboard_price_series_from_price(&price, "T1", "int4");
        assert_eq!(series.len(), 2);
        let image = series
            .iter()
            .find(|series| series.unit == USAGE_IMAGE)
            .unwrap();
        let step = series
            .iter()
            .find(|series| series.unit == USAGE_STEP)
            .unwrap();
        assert_eq!(image.points[0].price_au, 450);
        assert_eq!(step.points[0].price_au, 3);
        assert_ne!(image.points[0].price_au, step.points[0].price_au);

        let mut model = test_model();
        model.mayhem.adapter.endpoint_families = vec![
            mayhem_proto::endpoint_family_contract_template(
                mayhem_proto::ENDPOINT_OPENAI_IMAGE_GENERATIONS,
            )
            .unwrap(),
            mayhem_proto::endpoint_family_contract_template(
                mayhem_proto::ENDPOINT_HF_TEXT_TO_IMAGE,
            )
            .unwrap(),
        ];
        let abilities = dashboard_model_abilities(&model);
        assert!(abilities.contains(&format!(
            "api:{}",
            mayhem_proto::ENDPOINT_OPENAI_IMAGE_GENERATIONS
        )));
        assert!(abilities.contains(&format!("api:{}", mayhem_proto::ENDPOINT_HF_TEXT_TO_IMAGE)));
    }

